#!/bin/sh
# SPDX-License-Identifier: AGPL-3.0-only
#
# Pack the files generated by "make all-indep" into the auxiliary distfile
# used by the FreeBSD, pkgsrc and OpenBSD ports.
#
# The archive is laid out with a top-level "akvorado-<commit>/" directory,
# matching the WRKSRC created by the GitHub source archive, so every ports
# framework extracts it straight into the source tree without any custom
# post-extract step.
#
# Usage (from a git checkout at the commit to package, after running
# "make all-indep" so that all generated files exist):
#
#   bsd/make-generated-assets.sh [output-directory]
#
# Requires a libarchive-based tar (FreeBSD, macOS). The archive is
# deterministic: fixed owner, mode, member order and mtime (commit time), and
# no timestamp in the gzip header.

set -eu

out=${1:-.}
commit=$(git rev-parse HEAD)
version=${AKVORADO_PORT_VERSION:-$(git log -1 --format=%cd --date=format-local:%Y%m%d)}
stamp=$(TZ=UTC git log -1 --format=%cd --date=format-local:%Y%m%d%H%M.%S)
name=akvorado-${version}-generated-assets.tar.gz

# Generated files that are not committed. Keep in sync with GENERATED_GO in
# the top-level Makefile (eBPF objects and protocols.csv are committed and
# excluded here).
files="
common/embed/data/embed.zip
common/kafka/loadbalancealgorithm_enumer.go
common/kafka/saslmechanism_enumer.go
common/pb/rawflow.pb.go
common/remotedatasource/paginationtype_enumer.go
common/remotedatasource/parsertype_enumer.go
common/schema/definition_gen.go
console/filter/parser.go
console/homepagetopwidget_enumer.go
orchestrator/clickhouse/data/asns.csv
orchestrator/clickhouse/data/tcp.csv
orchestrator/clickhouse/data/udp.csv
outlet/clickhouse/serverselectionalgorithm_enumer.go
outlet/core/asnprovider_enumer.go
outlet/core/netprovider_enumer.go
outlet/metadata/provider/gnmi/ifspeedpathunit_enumer.go
outlet/metadata/provider/snmp/authprotocol_enumer.go
outlet/metadata/provider/snmp/privprotocol_enumer.go
"

for f in $files; do
    [ -f "$f" ] || { echo "missing generated file: $f (run make all-indep)" >&2; exit 1; }
    git ls-files --error-unmatch "$f" > /dev/null 2>&1 && \
        { echo "$f is committed, it should not be in the distfile" >&2; exit 1; }
    chmod 0644 "$f"
    TZ=UTC touch -t "$stamp" "$f"
done

printf '%s\n' $files | LC_ALL=C sort | \
    tar --uid 0 --gid 0 --uname root --gname wheel \
        --options gzip:!timestamp \
        -s ",^,akvorado-${commit}/," \
        -czf "${out}/${name}" -T -

echo "${out}/${name}"
sha256sum "${out}/${name}" 2> /dev/null || sha256 "${out}/${name}" 2> /dev/null || shasum -a 256 "${out}/${name}"
